<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {api} from '../api';import {useWorkspace,type WorkTab} from '../stores';
const props=defineProps<{tab:WorkTab}>(),work=useWorkspace();const data=ref<any>(null),month=ref(''),showResigned=ref(false),query=ref(''),loading=ref(false),error=ref('');let sequence=0;
const positions=['總經理','副總經理','資深經理','經理','督導','督導(代理店長)','店長','代理店長','副店長','主任','資深副理','副理','組長','資深專員','高級專員','專員','出納專員','助理','新人','行政','兼職藥師','兼職專員','兼職助理'];
const statuses:Record<string,string>={full_month:'整月在職',new_hire:'到職',resigned:'離職',leave_of_absence:'留停',transferred_in:'調入',transferred_out:'調出',promoted:'升職',support_rotation:'支援卡班',dual_store_manager:'雙店長',leave_return:'留停復職'};
const rank=(p:string)=>positions.includes(p)?positions.indexOf(p):999;
const rows=computed(()=>(data.value?.records||[]).filter((r:any)=>(showResigned.value||r.monthly_status!=='resigned')&&[r.employee_code,r.employee_name,r.position].join(' ').toLowerCase().includes(query.value.toLowerCase())).sort((a:any,b:any)=>rank(a.position)-rank(b.position)||(a.employee_name||'').localeCompare(b.employee_name||'','zh-TW')||(a.employee_code||'').localeCompare(b.employee_code||'')));
const counts=computed(()=>({active:(data.value?.records||[]).filter((r:any)=>r.monthly_status!=='resigned').length,resigned:(data.value?.records||[]).filter((r:any)=>r.monthly_status==='resigned').length}));
async function load(){const id=++sequence;loading.value=true;error.value='';try{const d=await api('store-employees?'+new URLSearchParams({store:props.tab.recordId||props.tab.store,month:month.value}));if(id!==sequence)return;data.value=d;month.value=d.month;props.tab.title='門市員工 · '+d.store.store_name+' · '+d.month;}catch(e){if(id!==sequence)return;data.value=null;error.value=(e as Error).message;}finally{if(id===sequence)loading.value=false;}}
function openMonthly(){const tab=work.open('monthly',data.value.store.id);if(data.value.month)tab.month=data.value.month;}
onMounted(load);
</script><template><header class="page-heading"><div><p class="eyebrow">組織與門市 / 門市員工</p><h1>{{data?.store.store_name||'門市員工'}}</h1><p v-if="data" class="muted">{{data.store.store_code}} · 每月人員名單</p></div><div class="module-actions"><button v-if="data?.canOpenMonthly" @click="openMonthly">開啟每月人員狀態</button><button :disabled="loading" @click="load">重新整理</button></div></header><p v-if="error" role="alert" class="notice error">{{error}}</p><div class="employee-filters"><label v-if="data?.months.length">查詢月份<select v-model="month" :disabled="loading" @change="load"><option v-for="m in data.months" :key="m" :value="m">{{m}}</option></select></label><label>搜尋員工<input v-model="query" placeholder="姓名、員編或職位"></label><label class="check"><input type="checkbox" v-model="showResigned">顯示離職員工</label></div><p v-if="loading" role="status">載入門市員工…</p><template v-else-if="data"><p class="muted">資料來源為每月人員狀態；此頁供查閱，更新請使用每月人員狀態。</p><p v-if="!data.months.length" class="notice">尚無可查看的每月人員狀態資料。</p><template v-else><p class="employee-summary">{{data.month}} · 在職 {{counts.active}} 人 · 離職 {{counts.resigned}} 人 · 目前顯示 {{rows.length}} 人</p><div class="module-table"><table><thead><tr><th>員編</th><th>姓名</th><th>職位</th><th>類型</th><th>本月狀態</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id" :class="{resigned:r.monthly_status==='resigned'}"><td>{{r.employee_code||'—'}}</td><td>{{r.employee_name||'—'}}<span v-if="r.is_pharmacist" class="pharmacist"> · 藥師</span></td><td>{{r.position||'—'}}</td><td>{{r.employment_type==='part_time'?'兼職':r.employment_type==='full_time'?'全職':r.employment_type||'—'}}</td><td>{{statuses[r.monthly_status]||r.monthly_status||'未提供'}}</td></tr><tr v-if="!rows.length"><td colspan="5">目前月份與篩選條件下無可查看的人員。</td></tr></tbody></table></div></template></template></template><style scoped>.employee-filters{display:flex;align-items:end;flex-wrap:wrap;gap:20px}.employee-filters label{display:grid;gap:8px}.employee-filters .check{display:flex;align-items:center;padding:10px}.check input{min-width:18px;min-height:18px;width:18px;height:18px}.employee-summary{padding:14px 0;border-block:1px solid var(--line)}.resigned{color:var(--muted)}.pharmacist{color:var(--primary)}.module-table td{white-space:normal;overflow-wrap:anywhere}@media(max-width:650px){.module-table table{min-width:0;table-layout:fixed}.module-table td,.module-table th{padding:8px 4px;font-size:12px}}</style>
